//! Integer FST enumeration over the exact Java-generated BYTE4 fixture bytes.
//! Java twin: `benchmarks/micro/java/IntsRefFstEnumMicro.java`.

use std::hint::black_box;
use std::time::Duration;

use lucene_codecs::fst::PositiveIntOutputs;
use lucene_codecs::fst_util::{IntsRefFstEnum, TypedFst};

use super::measure;

fn add(hash: &mut u64, word: u64) {
    *hash = (*hash ^ word).wrapping_mul(0x100000001b3);
}

fn result(hash: &mut u64, pair: Option<(&[i32], &i64)>) {
    if let Some((input, output)) = pair {
        add(hash, input.len() as u64);
        for &label in input {
            add(hash, label as u64);
        }
        add(hash, *output as u64);
    } else {
        add(hash, u64::MAX);
    }
}

fn run(fst: &TypedFst<PositiveIntOutputs>, probes: &[Vec<i32>], mode: &str) -> u64 {
    let mut cursor = IntsRefFstEnum::new(fst);
    let mut hash = 0xcbf29ce484222325;
    if mode == "next" {
        while let Some(pair) = cursor.next().unwrap() {
            result(&mut hash, Some(pair));
        }
    } else {
        for probe in probes {
            let pair = match mode {
                "exact" => cursor.seek_exact(probe).unwrap(),
                "ceil" => cursor.seek_ceil(probe).unwrap(),
                "floor" => cursor.seek_floor(probe).unwrap(),
                _ => unreachable!(),
            };
            result(&mut hash, pair);
        }
    }
    hash
}

pub fn bench_ints_ref_fst_enum(warmup: Duration, measure_time: Duration) {
    let dir = std::path::Path::new("fixtures/data/ints_ref_fst_enum");
    let fst =
        TypedFst::<PositiveIntOutputs>::read(&std::fs::read(dir.join("continuous.fst")).unwrap())
            .unwrap();
    let trace = std::fs::read_to_string(dir.join("continuous.txt")).unwrap();
    let keys: Vec<Vec<i32>> = trace
        .lines()
        .filter_map(|line| {
            let key = line.strip_prefix("key ")?.split(' ').next().unwrap();
            Some(if key == "-" {
                Vec::new()
            } else {
                key.split(',').map(|v| v.parse().unwrap()).collect()
            })
        })
        .collect();
    let mut probes = Vec::new();
    for key in &keys {
        probes.push(key.clone());
        let mut longer = key.clone();
        longer.push(1);
        probes.push(longer);
    }
    // The same deterministic reverse order drives prefix reuse and rewinds in both engines.
    probes.reverse();
    for mode in ["next", "exact", "ceil", "floor"] {
        let name = format!("ints_enum_{mode}");
        println!("#check\t{name}\t{:016x}", run(&fst, &probes, mode));
        let units = if mode == "next" {
            keys.len()
        } else {
            probes.len()
        } as u64;
        measure(&name, warmup, measure_time, || {
            black_box(run(&fst, &probes, mode));
            units
        });
    }
}
